&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Vous &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;maîtrisez : Suite Google/ Pack Office..&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
